from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def squares(xs: list[int]) -> list[int]:
    """Return [square(x) for x in xs], computed in parallel on a thread pool.

    The output preserves the order of the input. An empty input returns an
    empty list. The input list is not modified.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(square, xs))


def test_squares_empty() -> None:
    assert squares([]) == []


def test_squares_basic() -> None:
    assert squares([1, 2, 3]) == [1, 4, 9]


def test_squares_negatives_and_zero() -> None:
    assert squares([-3, 0, 4]) == [9, 0, 16]


def test_squares_preserves_order() -> None:
    xs = list(range(-500, 500))
    assert squares(xs) == [x * x for x in xs]


def test_squares_does_not_mutate_input() -> None:
    xs = [2, -5, 7]
    original = list(xs)
    squares(xs)
    assert xs == original


def test_squares_returns_new_list() -> None:
    xs = [1, 2]
    out = squares(xs)
    assert out is not xs


@pytest.mark.parametrize("n", [1, 2, 8, 64])
def test_squares_length_matches_input(n: int) -> None:
    xs = list(range(n))
    assert len(squares(xs)) == n
